    let needle = load_needle();
    let file = fs::File::open(INPUT_PATH)?;
    let reader = BufReader::new(file);

    let mut count: u64 = 0;
    for line in reader.lines() {
        let line = line?;
        if line.contains(&needle) {
            count += 1;
        }
    }

    println!("{}", count);
    Ok(())
}

