fn contains_error[&r](line: &r [byte]) -> [] bool {
    let needle = "ERROR";
    var i = 0;
    while i + len(needle) <= len(line) {
        var j = 0;
        var same = true;
        while j < len(needle) && same {
            if line[i + j] != needle[j] {
                same = false;
            }
            j = j + 1;
        }
        if same {
            return true;
        }
        i = i + 1;
    }
    return false;
}

