use std::fs;
use std::io;
use std::path::Path;

fn count_in_dir(dir: &Path) -> io::Result<usize> {
    let mut total = 0;
    for entry in fs::read_dir(dir)? {
        let entry = entry?;
        let path = entry.path();
        let file_type = entry.file_type()?;
        if file_type.is_dir() {
            total += count_in_dir(&path).unwrap_or(0);
        } else if file_type.is_file() {
            if let Ok(content) = fs::read(&path) {
                let text = String::from_utf8_lossy(&content);
                total += text.lines().filter(|line| line.contains("ERROR")).count();
            }
        }
    }
    Ok(total)
}

fn main() {
    let root = Path::new("/var/folders/s5/pnld4xwd6m78ztb80vplzpjc0000gp/T/e4b-7663uaw5");
    let count = count_in_dir(root).unwrap_or(0);
    println!("{}", count);
}

