import std.buffer;
import std.io;

fn is_error_line[&r](line: &r [byte]) -> [] bool {
    var i = 0;
    while i + 4 < len(line) {
        if int_of(line[i]) == 69 && int_of(line[i + 1]) == 82 && int_of(line[i + 2]) == 82 && int_of(line[i + 3]) == 79 && int_of(line[i + 4]) == 82 {
            return true;
        }
        i = i + 1;
    }
    return false;
}

fn main(world: World) -> [] int {
    let Split { io, ffi, fs, heap, args, net, clock, signals, exec } = split(world);
    release(ffi); release(args); release(net); release(clock); release(signals); release(exec);
    var total = 0;
    borrow fs as &f in {
        region r {
            let text = alloc_slice[r](65536, byte_of(0));
            let got = fs_read(f, "/var/folders/s5/pnld4xwd6m78ztb80vplzpjc0000gp/T/e4b-hanfeute/data/input.log", text);
            if got > 0 {
                var start = 0;
                var i = 0;
                while i < got {
                    if int_of(text[i]) == 10 {
                        if is_error_line(text[start..i]) {
                            total = total + 1;
                        }
                        start = i + 1;
                    }
                    i = i + 1;
                }
                if start < got && is_error_line(text[start..got]) {
                    total = total + 1;
                }
            }
        }
    }
    release(fs);
    borrow mut heap as &!h in {
        var out = buffer.empty(h, 16);
        out = buffer.push_nat(h, out, total);
        out = buffer.push(h, out, byte_of(10));
        borrow out as &o in {
            borrow mut io as &!i in {
                io.write_all(i, buffer.bytes(o));
            }
        }
        buffer.drop(h, out);
    }
    release(heap);
    release(io);
    return 0;
}

use std::fs;
use std::io::{self, BufRead, BufReader, Read};
use std::path::{Component, Path, PathBuf};

const BASE: &str = "/var/folders/s5/pnld4xwd6m78ztb80vplzpjc0000gp/T/e4b-_zyadcps/data";

fn main() {
    let mut line = String::new();
    if io::stdin().lock().read_line(&mut line).is_err() {
        println!("0");
        return;
    }
    let name = line.trim_end_matches(['\n', '\r']);

    let count = count_errors(name).unwrap_or_default();
    println!("{}", count);
}

fn count_errors(name: &str) -> Option<usize> {
    if name.is_empty() {
        return None;
    }
    let rel = Path::new(name);
    // Reject absolute paths and any parent-directory components up front.
    for comp in rel.components() {
        match comp {
            Component::Normal(_) | Component::CurDir => {}
            _ => return None,
        }
    }

    let base = fs::canonicalize(BASE).ok()?;
    let joined: PathBuf = base.join(rel);
    // Resolve symlinks and verify the real target is inside the base directory.
    let real = fs::canonicalize(&joined).ok()?;
    if !real.starts_with(&base) {
        return None;
