const ROOT: &str = "/var/folders/s5/pnld4xwd6m78ztb80vplzpjc0000gp/T/e4b-y4rkl5qt";

fn count_in_file(path: &Path) -> io::Result<usize> {
    let content = fs::read(path)?;
    let text = String::from_utf8_lossy(&content);
    Ok(text.lines().filter(|line| line.contains("ERROR")).count())
}

fn walk(dir: &Path, total: &mut usize) -> io::Result<()> {
    for entry in fs::read_dir(dir)? {
        let entry = match entry {
            Ok(e) => e,
            Err(_) => continue,
        };
        let path = entry.path();
        let file_type = match entry.file_type() {
            Ok(ft) => ft,
            Err(_) => continue,
        };
        if file_type.is_symlink() {
            continue;
        }
        if file_type.is_dir() {
            let _ = walk(&path, total);
        } else if file_type.is_file() {
            if let Ok(n) = count_in_file(&path) {
                *total += n;
            }
        }
    }
    Ok(())
}

fn main() {
    let mut total = 0usize;
    let root = Path::new(ROOT);
    if root.is_file() {
        if let Ok(n) = count_in_file(root) {
            total += n;
        }
    } else {
        let _ = walk(root, &mut total);
    }
    println!("{}", total);
}

