Writes only: standard output (a single line with the count)
"""

INPUT_PATH = "/var/folders/s5/pnld4xwd6m78ztb80vplzpjc0000gp/T/e4b-_otjdv8p/data/input.log"


def count_error_lines(path: str) -> int:
    count = 0
    with open(path, "r", encoding="utf-8", errors="replace") as handle:
        for line in handle:
