use std::fs;
use std::io::{self, BufRead, BufReader};
use std::path::{Component, Path, PathBuf};

const DATA_DIR: &str = "/var/folders/s5/pnld4xwd6m78ztb80vplzpjc0000gp/T/e4b-xc9ev3je/data";

fn main() {
    let stdin = io::stdin();
    let mut line = String::new();
    if stdin.lock().read_line(&mut line).is_err() {
        println!("0");
        return;
    }
    let name = line.trim_end_matches(['\n', '\r']);

    let count = count_errors(name).unwrap_or_default();
    println!("{}", count);
}

fn count_errors(name: &str) -> Option<usize> {
    let base = fs::canonicalize(DATA_DIR).ok()?;

    // Reject absolute paths and any parent-directory components up front.
    let rel = Path::new(name);
    if rel.is_absolute() {
        return None;
    }
    if rel.components().any(|c| matches!(c, Component::ParentDir | Component::RootDir | Component::Prefix(_))) {
        return None;
    }

    let candidate: PathBuf = base.join(rel);
    // Resolve symlinks and confirm the real target lies inside the data directory.
    let real = fs::canonicalize(&candidate).ok()?;
    if !real.starts_with(&base) {
        return None;
    }

    let meta = fs::metadata(&real).ok()?;
    if !meta.is_file() {
        return None;
    }

    let file = fs::File::open(&real).ok()?;
    let reader = BufReader::new(file);
    let mut count = 0usize;
    for l in reader.split(b'\n') {
        let bytes = l.ok()?;
        if contains_subslice(&bytes, b"ERROR") {
            count += 1;
        }
    }
    Some(count)
}

fn contains_subslice(hay: &[u8], needle: &[u8]) -> bool {
    hay.windows(needle.len()).any(|w| w == needle)
}

