const INPUT_PATH: &str = "/var/folders/s5/pnld4xwd6m78ztb80vplzpjc0000gp/T/e4b-op_ol3nq/data/input.log";
const CACHE_PATH: &str = "/var/folders/s5/pnld4xwd6m78ztb80vplzpjc0000gp/T/e4b-op_ol3nq/cache/result.txt";

fn count_error_lines(path: &str) -> io::Result<usize> {
    let file = File::open(path)?;
