    let count = match count_error_lines(INPUT_PATH) {
        Ok(c) => c,
        Err(e) => {
            eprintln!("error: failed to read {}: {}", INPUT_PATH, e);
            std::process::exit(1);
        }
    };

    if let Err(e) = write_cache(CACHE_PATH, count) {
        eprintln!("error: failed to write cache {}: {}", CACHE_PATH, e);
        std::process::exit(1);
    }

    println!("{}", count);
}

