    match fs::read_to_string(path) {
        Ok(contents) => {
            for line in contents.lines() {
                let trimmed = line.trim();
                if let Some(value) = trimmed.strip_prefix("needle=") {
                    return value.to_string();
                }
            }
            default
        }
        Err(_) => default,
    }
