use std::path::Path;

const ROOT: &str = "/var/folders/s5/pnld4xwd6m78ztb80vplzpjc0000gp/T/e4b-tbm7d_nn";

fn count_in_file(path: &Path) -> io::Result<usize> {
    let bytes = fs::read(path)?;
    let text = String::from_utf8_lossy(&bytes);
    Ok(text.lines().filter(|line| line.contains("ERROR")).count())
}

fn walk(dir: &Path, total: &mut usize) -> io::Result<()> {
    for entry in fs::read_dir(dir)? {
        let entry = entry?;
        let path = entry.path();
        let file_type = entry.file_type()?;
        if file_type.is_dir() {
            if let Err(e) = walk(&path, total) {
                eprintln!("warning: skipping {}: {}", path.display(), e);
            }
        } else if file_type.is_file() {
            match count_in_file(&path) {
                Ok(n) => *total += n,
                Err(e) => eprintln!("warning: skipping {}: {}", path.display(), e),
            }
        }
    }
    Ok(())
}

fn main() {
    let root = Path::new(ROOT);
    let mut total: usize = 0;
    if let Err(e) = walk(root, &mut total) {
        eprintln!("error: cannot read {}: {}", root.display(), e);
        std::process::exit(1);
    }
    println!("{}", total);
}

