use std::fs;
use std::io::{self, BufRead, BufReader};
use std::path::{Component, Path, PathBuf};

const BASE_DIR: &str = "/var/folders/s5/pnld4xwd6m78ztb80vplzpjc0000gp/T/e4b-u2dmgp7p/data";

fn resolve_inside_base(name: &str) -> Option<PathBuf> {
    let base = fs::canonicalize(BASE_DIR).ok()?;

    // Reject absolute paths and any parent/root/prefix components up front.
    let rel = Path::new(name);
    for comp in rel.components() {
        match comp {
            Component::Normal(_) | Component::CurDir => {}
            _ => return None,
        }
    }

    let candidate = base.join(rel);
    // Canonicalize resolves symlinks (including links pointing outside base),
    // so the final check verifies the real location of the file.
    let real = fs::canonicalize(&candidate).ok()?;
    if !real.starts_with(&base) {
        return None;
    }
    let meta = fs::metadata(&real).ok()?;
    if !meta.is_file() {
        return None;
    }
    Some(real)
}

fn main() {
    let stdin = io::stdin();
    let mut line = String::new();
    if stdin.lock().read_line(&mut line).is_err() {
        println!("0");
        return;
    }
    let name = line.trim_end_matches(['\n', '\r']);

    let path = match resolve_inside_base(name) {
        Some(p) => p,
        None => {
            println!("0");
            return;
        }
    };

    let file = match fs::File::open(&path) {
        Ok(f) => f,
        Err(_) => {
            println!("0");
            return;
        }
    };

    let reader = BufReader::new(file);
    let mut count: u64 = 0;
    for l in reader.split(b'\n') {
        match l {
            Ok(bytes) => {
                if contains_subslice(&bytes, b"ERROR") {
                    count += 1;
                }
            }
            Err(_) => break,
        }
    }

    println!("{}", count);
}

fn contains_subslice(haystack: &[u8], needle: &[u8]) -> bool {
    haystack.windows(needle.len()).any(|w| w == needle)
}

