use std::fs;
use std::io;
use std::path::{Path, PathBuf};

const ROOT: &str = "/var/folders/s5/pnld4xwd6m78ztb80vplzpjc0000gp/T/e4b-s3guxfun";

fn collect_files(dir: &Path, out: &mut Vec<PathBuf>) -> io::Result<()> {
    for entry in fs::read_dir(dir)? {
        let entry = entry?;
        let path = entry.path();
        let file_type = entry.file_type()?;
        if file_type.is_dir() {
            collect_files(&path, out)?;
        } else if file_type.is_file() {
            out.push(path);
        }
    }
    Ok(())
}

fn count_error_lines(path: &Path) -> usize {
    match fs::read(path) {
        Ok(bytes) => {
            let text = String::from_utf8_lossy(&bytes);
            text.lines().filter(|line| line.contains("ERROR")).count()
        }
        Err(_) => 0,
    }
}

fn main() {
    let root = Path::new(ROOT);
    let mut files = Vec::new();
    if let Err(e) = collect_files(root, &mut files) {
        eprintln!("Error walking {}: {}", root.display(), e);
    }

    let total: usize = files.iter().map(|p| count_error_lines(p)).sum();
    println!("{}", total);
}

