use std::io::{self, BufRead, BufReader};
use std::path::{Component, Path, PathBuf};

const BASE: &str = "/var/folders/s5/pnld4xwd6m78ztb80vplzpjc0000gp/T/e4b-prz7h8bh/data";

fn main() {
    let mut line = String::new();
    if io::stdin().lock().read_line(&mut line).is_err() {
        println!("0");
        return;
    }
    let name = line.trim_end_matches(['\n', '\r']);

    let base = match fs::canonicalize(BASE) {
        Ok(p) => p,
        Err(_) => {
            println!("0");
            return;
        }
    };

    // Reject absolute names and any component that is not a plain name.
    let rel = Path::new(name);
    let mut ok = !name.is_empty() && !rel.is_absolute();
    if ok {
        for c in rel.components() {
            match c {
                Component::Normal(_) => {}
                _ => {
                    ok = false;
                    break;
                }
            }
        }
    }
    if !ok {
        println!("0");
        return;
    }

    let candidate: PathBuf = base.join(rel);
    // Resolve symlinks and check the real location lies inside BASE.
    let real = match fs::canonicalize(&candidate) {
        Ok(p) => p,
        Err(_) => {
            println!("0");
            return;
        }
    };
    if !real.starts_with(&base) || !real.is_file() {
        println!("0");
        return;
    }

    let file = match fs::File::open(&real) {
        Ok(f) => f,
        Err(_) => {
            println!("0");
            return;
        }
    };

    let reader = BufReader::new(file);
    let mut count: u64 = 0;
    for l in reader.split(b'\n') {
        match l {
            Ok(bytes) => {
                if bytes.windows(5).any(|w| w == b"ERROR") {
                    count += 1;
                }
            }
            Err(_) => break,
        }
    }

    println!("{}", count);
}

