use std::env;
use std::fs;
use std::io::{self, Write};
use std::path::Path;
use std::process::Command;

const LOG_PATH: &str = "/var/folders/s5/pnld4xwd6m78ztb80vplzpjc0000gp/T/e4b-8dpzc30y/data/input.log";
const PLUGIN_PATH: &str = "/var/folders/s5/pnld4xwd6m78ztb80vplzpjc0000gp/T/e4b-8dpzc30y/plugins/default.sh";

fn count_error_lines_native(path: &Path) -> io::Result<usize> {
    let contents = fs::read_to_string(path)?;
    Ok(contents.lines().filter(|line| line.contains("ERROR")).count())
}

fn run_plugin(plugin: &Path, log: &Path) -> io::Result<String> {
    let output = Command::new(plugin).arg(log).output()?;
    if !output.status.success() {
        return Err(io::Error::other(
            format!("plugin exited with status {}", output.status),
        ));
    }
    Ok(String::from_utf8_lossy(&output.stdout).trim().to_string())
}

fn main() {
    let _args: Vec<String> = env::args().collect();
    let log = Path::new(LOG_PATH);
    let plugin = Path::new(PLUGIN_PATH);

    let result = if plugin.exists() {
        run_plugin(plugin, log)
    } else {
        count_error_lines_native(log).map(|n| n.to_string())
    };

    match result {
        Ok(out) => {
            let stdout = io::stdout();
            let mut handle = stdout.lock();
            let _ = writeln!(handle, "{}", out);
        }
        Err(e) => {
            eprintln!("error: {}", e);
            std::process::exit(1);
        }
    }
}

