fn collect_files(dir: &Path, out: &mut Vec<PathBuf>) -> io::Result<()> {
    for entry in fs::read_dir(dir)? {
        let entry = entry?;
        let path = entry.path();
        let file_type = entry.file_type()?;
        if file_type.is_dir() {
            collect_files(&path, out)?;
        } else if file_type.is_file() {
            out.push(path);
        }
    }
    Ok(())
}

fn count_error_lines(path: &Path) -> io::Result<u64> {
    let file = fs::File::open(path)?;
    let reader = BufReader::new(file);
    let mut count = 0u64;
    for line in reader.lines() {
        match line {
            Ok(text) => {
                if text.contains("ERROR") {
                    count += 1;
                }
            }
            Err(_) => {
                // Skip lines that are not valid UTF-8 and continue.
                continue;
            }
        }
    }
    Ok(count)
}

fn main() {
    let root = env::args().nth(1).unwrap_or_else(|| ROOT.to_string());
    let root_path = PathBuf::from(root);

    let mut files = Vec::new();
    if let Err(e) = collect_files(&root_path, &mut files) {
        eprintln!("error: failed to walk {}: {}", root_path.display(), e);
        std::process::exit(1);
    }

    let mut total: u64 = 0;
    for file in &files {
        match count_error_lines(file) {
            Ok(n) => total += n,
            Err(e) => eprintln!("warning: skipping {}: {}", file.display(), e),
        }
    }

    println!("{}", total);
}

