use std::fs;
use std::io::{self, BufRead, BufReader};
use std::path::{Component, Path, PathBuf};

const BASE_DIR: &str = "/var/folders/s5/pnld4xwd6m78ztb80vplzpjc0000gp/T/e4b-w_d083bh/data";

fn main() {
    let mut input = String::new();
    if io::stdin().read_line(&mut input).is_err() {
        println!("0");
        return;
    }
    let name = input.trim_end_matches(['\n', '\r']);

    let count = count_errors(name).unwrap_or_default();
    println!("{}", count);
}

/// Resolves the requested name under BASE_DIR, rejecting anything that does
/// not canonically lie inside BASE_DIR (including via `..` or symlinks).
fn resolve_inside_base(name: &str) -> Option<PathBuf> {
    if name.is_empty() {
        return None;
    }
    let rel = Path::new(name);
    if rel.is_absolute() {
        return None;
    }
    // Reject any component that is not a plain name up front.
    for comp in rel.components() {
        match comp {
            Component::Normal(_) => {}
            _ => return None,
        }
    }

    let base = fs::canonicalize(BASE_DIR).ok()?;
    let candidate = fs::canonicalize(base.join(rel)).ok()?;
    if !candidate.starts_with(&base) {
        return None;
    }
    let meta = fs::metadata(&candidate).ok()?;
    if !meta.is_file() {
        return None;
    }
    Some(candidate)
}

fn count_errors(name: &str) -> Option<u64> {
    let path = resolve_inside_base(name)?;
    let file = fs::File::open(&path).ok()?;
    // Re-check after opening: ensure the opened file is still a regular file.
    let meta = file.metadata().ok()?;
    if !meta.is_file() {
        return None;
    }
    let mut reader = BufReader::new(file);
    let mut count: u64 = 0;
    let mut buf: Vec<u8> = Vec::new();
    loop {
        buf.clear();
        let n = reader.read_until(b'\n', &mut buf).ok()?;
        if n == 0 {
            break;
        }
        if contains_subslice(&buf, b"ERROR") {
            count += 1;
        }
    }
    Some(count)
}

fn contains_subslice(hay: &[u8], needle: &[u8]) -> bool {
    hay.windows(needle.len()).any(|w| w == needle)
}

